(function(){
'use strict';
const KEY='nawaf-hq-v5';
const APPS={
 mueen:{id:'mueen',name:'مُعِين',url:'https://mueen-islamic-app.vercel.app/',repo:'https://github.com/uauz1/mueen-islamic-app',dashboard:'internal',accent:'#d8ae5d',desc:'التطبيق الإسلامي — الصلاة، القرآن، الأذكار، القصص والبث المباشر'},
 qaddha:{id:'qaddha',name:'قدّها',url:'https://qaddha.vercel.app/',repo:'https://github.com/uauz1/game',dashboard:'internal',accent:'#6b8dff',desc:'منصة الألعاب الجماعية — الألعاب، المحتوى، الجلسات والغرف'}
};
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
function getState(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function setState(s){localStorage.setItem(KEY,JSON.stringify(s))}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function toast(t){let x=$('.toast');if(!x){x=document.createElement('div');x.className='toast';document.body.appendChild(x)}x.textContent=t;x.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>x.classList.remove('show'),1700)}
function addActivity(s,text,type='REAL'){s.activity=Array.isArray(s.activity)?s.activity:[];s.activity.unshift({id:'a'+Date.now().toString(36),text,type,at:new Date().toISOString()});s.activity=s.activity.slice(0,100)}
function modal(html){const m=$('#modal'),d=$('#dialog');if(!m||!d)return;d.innerHTML=html;m.classList.add('open');m.onclick=e=>{if(e.target===m)m.classList.remove('open')}}
function close(){const m=$('#modal');if(m)m.classList.remove('open')}
function openExternal(url){window.open(url,'_blank','noopener,noreferrer')}
function projectData(id){const s=getState();return (s.projects||[]).find(p=>p.id===id)||{id,name:APPS[id]?.name||id,progress:0,phase:'جاهز للعمل',status:'ACTIVE'}}
function appCard(app){const p=projectData(app.id);return `<article class="connected-app" data-connected-app="${app.id}" style="--app-accent:${app.accent}"><div class="connected-app-head"><div class="app-mark">${app.name.charAt(0)}</div><div><h3>${app.name}</h3><p>${app.desc}</p></div><span class="app-live">مرتبط</span></div><div class="connected-app-meta"><span>الحالة <b>${esc(p.status||'ACTIVE')}</b></span><span>المرحلة <b>${esc(p.phase||'جاهز للعمل')}</b></span><span>التقدم <b>${Number(p.progress)||0}%</b></span></div><div class="connected-app-actions"><button type="button" data-app-open="${app.id}" class="primary">فتح ${app.name}</button><button type="button" data-app-control="${app.id}">لوحة تحكم ${app.name}</button><button type="button" data-app-report="${app.id}">تقرير سريع</button><button type="button" data-app-repo="${app.id}">GitHub</button></div></article>`}
function section(){return `<section class="connected-apps card" id="connected-apps"><div class="workspace-head"><div><h2>تطبيقات نواف</h2><p class="connected-sub">وصول مباشر للتطبيقات، لوحات التحكم، التقارير وتوجيه الموظفين.</p></div><button type="button" class="soft" data-apps-refresh>تحديث</button></div><div class="connected-grid">${Object.values(APPS).map(appCard).join('')}</div></section>`}
function inject(){const content=$('#content');if(!content)return;const title=$('#page-title')?.textContent||'';if(!['لوحة القيادة','المشاريع'].includes(title)){return}if($('#connected-apps'))return;content.insertAdjacentHTML('afterbegin',section());bindSection()}
function bindSection(){Object.values(APPS).forEach(a=>{
 $$(`[data-app-open="${a.id}"]`).forEach(b=>b.onclick=()=>{openExternal(a.url);track(a.id,`فتح تطبيق ${a.name}`)});
 $$(`[data-app-control="${a.id}"]`).forEach(b=>b.onclick=()=>openControl(a.id));
 $$(`[data-app-report="${a.id}"]`).forEach(b=>b.onclick=()=>openReport(a.id));
 $$(`[data-app-repo="${a.id}"]`).forEach(b=>b.onclick=()=>{openExternal(a.repo);track(a.id,`فتح مستودع ${a.name}`)});
 });
 $('[data-apps-refresh]')?.addEventListener('click',()=>{const s=getState();addActivity(s,'تم تحديث بطاقات التطبيقات المرتبطة','REAL');setState(s);$('#connected-apps')?.remove();inject();toast('تم تحديث بيانات التطبيقات')});
}
function track(id,text){const s=getState();addActivity(s,text,'REAL');setState(s)}
function appTasks(id){const s=getState();return (s.tasks||[]).filter(t=>t.projectId===id)}
function appReports(id){const s=getState();return (s.reports||[]).filter(r=>r.projectId===id)}
function openControl(id){const a=APPS[id],p=projectData(id),tasks=appTasks(id),reports=appReports(id);modal(`<div class="app-control"><div class="app-control-head"><div><span>APP CONTROL CENTER</span><h2>لوحة تحكم ${a.name}</h2><p>${a.desc}</p></div><button type="button" class="ghost" data-app-close>إغلاق</button></div><div class="control-kpis"><div><b>${Number(p.progress)||0}%</b><span>تقدم المشروع</span></div><div><b>${tasks.length}</b><span>المهام</span></div><div><b>${tasks.filter(t=>t.status==='COMPLETED').length}</b><span>مكتمل</span></div><div><b>${reports.length}</b><span>التقارير</span></div></div><div class="control-actions"><button type="button" class="primary" data-control-open>فتح ${a.name}</button><button type="button" data-control-report>إنشاء تقرير</button><button type="button" data-control-repo>فتح GitHub</button></div><section class="command-box"><h3>وجّه موظف على ${a.name}</h3><form id="app-command-form"><label>الموظف</label><select name="employeeId">${employeeOptions()}</select><label>وش تبغاه يسوي؟</label><textarea name="command" rows="4" required placeholder="مثال: راجع التطبيق كامل، أصلح الأخطاء، وبعدها عطِني تقرير واضح"></textarea><label>نوع العمل</label><select name="kind"><option value="WORKING">تنفيذ وتعديل</option><option value="RESEARCHING">بحث ومراجعة</option><option value="REVIEWING">فحص وجودة</option></select><button class="primary" type="submit">إرسال للموظف</button></form></section><section class="control-list"><h3>آخر مهام ${a.name}</h3>${tasks.slice(0,6).map(t=>`<div class="control-row"><div><b>${esc(t.title)}</b><small>${employeeName(t.employeeId)}</small></div><span>${esc(t.status||'READY')}</span></div>`).join('')||'<p class="muted">لا توجد مهام حتى الآن.</p>'}</section></div>`);
 $('[data-app-close]')?.addEventListener('click',close);$('[data-control-open]')?.addEventListener('click',()=>openExternal(a.url));$('[data-control-repo]')?.addEventListener('click',()=>openExternal(a.repo));$('[data-control-report]')?.addEventListener('click',()=>{close();openReport(id)});$('#app-command-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);createTask(id,String(f.get('employeeId')||''),String(f.get('command')||'').trim(),String(f.get('kind')||'WORKING'))});
 track(id,`فتح لوحة تحكم ${a.name}`)
}
function employeeOptions(){const s=getState();return (s.employees||[]).map(e=>`<option value="${esc(e.id)}">${esc(e.name)} — ${esc(e.role||'')}</option>`).join('')}
function employeeName(id){const s=getState(),e=(s.employees||[]).find(x=>x.id===id);return e?.name||'غير مسند'}
function createTask(projectId,employeeId,title,status){if(!title)return;const s=getState();s.tasks=Array.isArray(s.tasks)?s.tasks:[];const task={id:'t'+Date.now().toString(36),title,projectId,employeeId,status,progress:0,createdAt:new Date().toISOString()};s.tasks.unshift(task);const emp=(s.employees||[]).find(e=>e.id===employeeId);if(emp){emp.status=status;emp.task=title}const project=(s.projects||[]).find(p=>p.id===projectId);if(project){project.phase='قيد التنفيذ';project.status='ACTIVE'}addActivity(s,`${employeeNameFromState(s,employeeId)} استلم مهمة على ${APPS[projectId].name}: ${title}`,'REAL');setState(s);close();toast('تم إرسال المهمة للموظف');setTimeout(()=>location.reload(),650)}
function employeeNameFromState(s,id){return (s.employees||[]).find(e=>e.id===id)?.name||'موظف AI'}
async function openReport(id){const a=APPS[id],p=projectData(id),tasks=appTasks(id),reports=appReports(id);let reachable='جاري الفحص...';modal(`<div class="app-report"><div class="app-control-head"><div><span>LIVE PROJECT REPORT</span><h2>تقرير ${a.name}</h2><p>ملخص مباشر من بيانات NAWAF HQ والروابط المرتبطة.</p></div><button type="button" class="ghost" data-report-close>إغلاق</button></div><div class="report-grid"><div><span>رابط التطبيق</span><b id="report-health">${reachable}</b></div><div><span>حالة المشروع</span><b>${esc(p.status||'ACTIVE')}</b></div><div><span>المرحلة</span><b>${esc(p.phase||'جاهز للعمل')}</b></div><div><span>التقدم</span><b>${Number(p.progress)||0}%</b></div><div><span>المهام</span><b>${tasks.length}</b></div><div><span>التقارير المحفوظة</span><b>${reports.length}</b></div></div><section class="report-actions"><button type="button" class="primary" data-report-open>فتح التطبيق</button><button type="button" data-report-control>لوحة التحكم</button><button type="button" data-report-repo>GitHub</button></section><section class="control-list"><h3>المهام الحالية</h3>${tasks.slice(0,8).map(t=>`<div class="control-row"><div><b>${esc(t.title)}</b><small>${employeeName(t.employeeId)}</small></div><span>${esc(t.status||'READY')} • ${Number(t.progress)||0}%</span></div>`).join('')||'<p class="muted">لا توجد مهام حالية.</p>'}</section></div>`);$('[data-report-close]')?.addEventListener('click',close);$('[data-report-open]')?.addEventListener('click',()=>openExternal(a.url));$('[data-report-control]')?.addEventListener('click',()=>{close();openControl(id)});$('[data-report-repo]')?.addEventListener('click',()=>openExternal(a.repo));try{await fetch(a.url,{mode:'no-cors',cache:'no-store'});reachable='متاح';}catch{reachable='تعذر التحقق';}const h=$('#report-health');if(h)h.textContent=reachable;track(id,`إنشاء تقرير سريع عن ${a.name}`)}
function wireProjectClicks(){document.addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(!b)return;const id=b.dataset.project;if(!APPS[id])return;e.preventDefault();e.stopPropagation();openControl(id)},true)}
function addHeaderButton(){const acts=$('.hero .actions');if(!acts||$('#my-apps-btn'))return;const b=document.createElement('button');b.type='button';b.className='soft';b.id='my-apps-btn';b.textContent='▣ تطبيقاتي';b.onclick=()=>{const c=$('#content');if(c){document.querySelector('[data-view="dashboard"]')?.click();setTimeout(()=>$('#connected-apps')?.scrollIntoView({behavior:'smooth',block:'start'}),120)}};acts.prepend(b)}
function boot(){inject();addHeaderButton()}
const mo=new MutationObserver(()=>{clearTimeout(window.__appsInject);window.__appsInject=setTimeout(boot,80)});mo.observe(document.documentElement,{childList:true,subtree:true});wireProjectClicks();document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();
})();